IF DB_ID('MarketingAlimentos') IS NULL
    CREATE DATABASE MarketingAlimentos;
GO

USE MarketingAlimentos;
GO

-- Remove tabelas antigas (permite rodar o script de novo)
DROP TABLE IF EXISTS ResultadosCampanha;
DROP TABLE IF EXISTS ItensPedido;
DROP TABLE IF EXISTS Pedidos;
DROP TABLE IF EXISTS Clientes;
DROP TABLE IF EXISTS Campanhas;
DROP TABLE IF EXISTS Canais;
DROP TABLE IF EXISTS Produtos;
DROP TABLE IF EXISTS Categorias;
GO

CREATE TABLE Categorias (
    categoria_id INT PRIMARY KEY,
    nome         NVARCHAR(50) NOT NULL
);

CREATE TABLE Produtos (
    produto_id   INT PRIMARY KEY,
    nome         NVARCHAR(100) NOT NULL,
    categoria_id INT NOT NULL REFERENCES Categorias(categoria_id),
    preco        DECIMAL(10,2) NOT NULL,
    custo        DECIMAL(10,2) NOT NULL
);

CREATE TABLE Canais (
    canal_id INT PRIMARY KEY,
    nome     NVARCHAR(50) NOT NULL,
    tipo     NVARCHAR(20) NOT NULL  -- Pago ou Orgânico
);

CREATE TABLE Campanhas (
    campanha_id INT PRIMARY KEY,
    nome        NVARCHAR(100) NOT NULL,
    canal_id    INT NOT NULL REFERENCES Canais(canal_id),
    data_inicio DATE NOT NULL,
    data_fim    DATE NOT NULL,
    orcamento   DECIMAL(10,2) NOT NULL
);

CREATE TABLE Clientes (
    cliente_id        INT PRIMARY KEY,
    nome              NVARCHAR(100) NOT NULL,
    cidade            NVARCHAR(60) NOT NULL,
    estado            CHAR(2) NOT NULL,
    data_cadastro     DATE NOT NULL,
    canal_aquisicao_id INT NOT NULL REFERENCES Canais(canal_id)
);

CREATE TABLE Pedidos (
    pedido_id   INT PRIMARY KEY,
    cliente_id  INT NOT NULL REFERENCES Clientes(cliente_id),
    campanha_id INT NULL REFERENCES Campanhas(campanha_id),  -- NULL = pedido sem campanha
    data_pedido DATE NOT NULL,
    status      NVARCHAR(20) NOT NULL  -- Entregue, Pendente ou Cancelado
);

CREATE TABLE ItensPedido (
    item_id        INT PRIMARY KEY,
    pedido_id      INT NOT NULL REFERENCES Pedidos(pedido_id),
    produto_id     INT NOT NULL REFERENCES Produtos(produto_id),
    quantidade     INT NOT NULL,
    preco_unitario DECIMAL(10,2) NOT NULL
);

CREATE TABLE ResultadosCampanha (
    resultado_id INT PRIMARY KEY,
    campanha_id  INT NOT NULL REFERENCES Campanhas(campanha_id),
    data         DATE NOT NULL,
    impressoes   INT NOT NULL,
    cliques      INT NOT NULL,
    gasto        DECIMAL(10,2) NOT NULL
);
GO

