-- Conferência rápida: quantidade de linhas por tabela
SELECT 'Categorias' AS tabela, COUNT(*) AS linhas FROM Categorias UNION ALL
SELECT 'Produtos', COUNT(*) FROM Produtos UNION ALL
SELECT 'Canais', COUNT(*) FROM Canais UNION ALL
SELECT 'Campanhas', COUNT(*) FROM Campanhas UNION ALL
SELECT 'Clientes', COUNT(*) FROM Clientes UNION ALL
SELECT 'Pedidos', COUNT(*) FROM Pedidos UNION ALL
SELECT 'ItensPedido', COUNT(*) FROM ItensPedido UNION ALL
SELECT 'ResultadosCampanha', COUNT(*) FROM ResultadosCampanha;
GO
